import { useContext, useEffect, useState, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import './messages.scss';

const Messages = () => {
  const { currentUser, accessToken } = useContext(AuthContext);
  const { friendId } = useParams();
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Messages: No profile picture provided, using default');
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Messages: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture
      .replace(/^\/(Uploads|post_upload|profile_upload)\//i, '/$1/')
      .replace(/^\/(post_upload|profile_upload)\//i, '/$1/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Messages: Profile picture URL:', url);
    return url;
  };

  const fetchMessages = useCallback(async () => {
    if (!accessToken || !friendId || !currentUser) {
      console.error('Messages: Missing required data', { accessToken: !!accessToken, friendId, currentUser: !!currentUser });
      setError('Please log in and select a friend to view messages.');
      return;
    }

    setLoading(true);
    setError(null);
    try {
      console.log('Messages: Fetching messages for friendId:', friendId);
      const res = await axios.get(`http://localhost:5000/api/users/messages/${friendId}`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      console.log('Messages: Fetch response=', {
        status: res.status,
        data: JSON.stringify(res.data, null, 2),
      });
      setMessages(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error('Messages: Error fetching messages:', err.message);
      console.error('Messages: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      if (err.response?.status === 401) {
        setError('Session expired. Please log in again.');
        navigate('/login');
      } else {
        setError(err.response?.data?.message || 'Failed to load messages.');
      }
    } finally {
      setLoading(false);
    }
  }, [accessToken, friendId, currentUser, navigate]);

  useEffect(() => {
    fetchMessages();
    const interval = setInterval(fetchMessages, 5000); // Poll every 5 seconds
    return () => clearInterval(interval);
  }, [fetchMessages]);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim()) {
      setError('Message cannot be empty.');
      return;
    }

    setLoading(true);
    setError(null);
    try {
      console.log('Messages: Sending message to friendId:', friendId);
      const res = await axios.post(
        'http://localhost:5000/api/users/messages',
        { recipientId: friendId, content: newMessage },
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      console.log('Messages: Send message response=', {
        status: res.status,
        data: JSON.stringify(res.data, null, 2),
      });
      setNewMessage('');
      fetchMessages(); // Refresh messages
    } catch (err) {
      console.error('Messages: Error sending message:', err.message);
      console.error('Messages: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      setError(err.response?.data?.message || 'Failed to send message.');
    } finally {
      setLoading(false);
    }
  };

  if (!currentUser) {
    return <div className="messages">Please log in to view messages.</div>;
  }

  return (
    <div className="messages">
      <h3>Messages with Friend</h3>
      {loading && <p>Loading messages...</p>}
      {error && <p className="error">{error}</p>}
      <div className="messages-list">
        {messages.length === 0 && !loading && !error && <p>No messages yet.</p>}
        {messages.map((msg) => (
          <div
            key={msg._id}
            className={`message ${msg.senderId._id === currentUser._id ? 'sent' : 'received'}`}
          >
            <img
              src={getProfilePictureUrl(msg.senderId.profilePicture)}
              alt={`${msg.senderId.username}'s profile`}
              className="avatar"
              onError={(e) => {
                e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
              }}
            />
            <div className="message-content">
              <span className="username">{msg.senderId.username}</span>
              <p>{msg.content}</p>
              <span className="timestamp">{new Date(msg.timestamp).toLocaleString()}</span>
            </div>
          </div>
        ))}
      </div>
      <form className="message-form" onSubmit={handleSendMessage}>
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type a message..."
          disabled={loading}
        />
        <button type="submit" disabled={loading}>Send</button>
      </form>
    </div>
  );
};

export default Messages;
